    cols=cols or list(rows[0].keys()); rename=rename or {}
    h=f'<div class="tblwrap"{" style=\"max-height:%s\"" % maxh if maxh else ""}><table class="sortable" id="{id_}"><thead><tr>'+''.join(f'<th>{html.escape(rename.get(c,c))}</th>' for c in cols)+'</tr></thead><tbody>'
